<?php
 namespace OSS\Model; use OSS\Core\OssException; class ServerSideEncryptionConfig implements XmlConfig { public function __construct($sseAlgorithm = null, $kmsMasterKeyID = null) { $this->sseAlgorithm = $sseAlgorithm; $this->kmsMasterKeyID = $kmsMasterKeyID; } public function parseFromXml($strXml) { $xml = simplexml_load_string($strXml); if (!isset($xml->ApplyServerSideEncryptionByDefault)) return; foreach ($xml->ApplyServerSideEncryptionByDefault as $default) { foreach ($default as $key => $value) { if ($key === 'SSEAlgorithm') { $this->sseAlgorithm = strval($value); } elseif ($key === 'KMSMasterKeyID') { $this->kmsMasterKeyID = strval($value); } } break; } } public function serializeToXml() { $xml = new \SimpleXMLElement('<?xml version="1.0" encoding="utf-8"?><ServerSideEncryptionRule></ServerSideEncryptionRule>'); $default = $xml->addChild('ApplyServerSideEncryptionByDefault'); if (isset($this->sseAlgorithm)) { $default->addChild('SSEAlgorithm', $this->sseAlgorithm); } if (isset($this->kmsMasterKeyID)) { $default->addChild('KMSMasterKeyID', $this->kmsMasterKeyID); } return $xml->asXML(); } public function __toString() { return $this->serializeToXml(); } public function getSSEAlgorithm() { return $this->sseAlgorithm; } public function getKMSMasterKeyID() { return $this->kmsMasterKeyID; } private $sseAlgorithm = ""; private $kmsMasterKeyID = ""; }